#include <bits/stdc++.h>
using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, K, U;
    if(!(cin >> N >> K >> U)) return 0;

    // Guarda todos os números das cartelas (virão antes da sequência de sorteios)
    vector<int> flat(static_cast<size_t>(N) * K);
    for(size_t i = 0; i < flat.size(); i++) cin >> flat[i];

    // pos[x] = momento (posição) em que o número x é sorteado
    vector<int> pos(U + 1, 0);
    for(int u = 1; u <= U; u++){
        int x;
        cin >> x;
        pos[x] = u;
    }

    int best = INT_MAX;
    vector<int> winners;

    size_t idx = 0;
    for(int i = 1; i <= N; i++){
        int t = 0;
        for(int j = 0; j < K; j++, idx++){
            int q = pos[flat[idx]];
            if(q > t) t = q;
        }
        if(t < best){
            best = t;
            winners.clear();
            winners.push_back(i);
        } else if(t == best){
            winners.push_back(i);
        }
    }

    for(size_t j = 0; j < winners.size(); j++){
        if(j) cout << ' ';
        cout << winners[j];
    }
    cout << '\n';

    return 0;
}
